export interface ConnectorConfig {
  /** Asana Personal Access Token for Bearer authentication */
  asanaToken: string
  /** Asana Workspace GID (required) */
  workspaceGid: string
  /** Optional Asana Project GIDs to associate the task with */
  projectGids?: string[]
  /** Injected fetch for testing; defaults to global fetch */
  fetch?: typeof fetch
}

export interface JotformSubmissionPayload {
  /** Title of the Jotform form */
  formTitle: string
  /** Internal Jotform submission ID */
  submissionId: string
  /** Dynamic form fields with keys like field_{field_id} */
  [key: `field_${string}`]: string | undefined
}

export interface AsanaTaskResponse {
  gid: string
  name: string
  notes: string
  resource_type: string
  workspace: {
    gid: string
    resource_type: string
    name: string
  }
}

export interface HandleResult {
  taskId: string
  taskName: string
  taskNotes: string
}

function buildDescription(payload: JotformSubmissionPayload): string {
  const lines: string[] = []
  for (const [key, value] of Object.entries(payload)) {
    if (key.startsWith('field_') && value !== undefined && value !== '') {
      const fieldId = key.replace('field_', '')
      lines.push(`${fieldId}: ${value}`)
    }
  }
  return lines.join('\n')
}

export async function handle(
  payload: JotformSubmissionPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  if (!payload.formTitle || typeof payload.formTitle !== 'string') {
    throw new Error('Missing required field: formTitle')
  }
  if (!payload.submissionId || typeof payload.submissionId !== 'string') {
    throw new Error('Missing required field: submissionId')
  }
  if (!config.asanaToken || typeof config.asanaToken !== 'string') {
    throw new Error('Missing required config: asanaToken')
  }
  if (!config.workspaceGid || typeof config.workspaceGid !== 'string') {
    throw new Error('Missing required config: workspaceGid')
  }

  const description = buildDescription(payload)

  const requestBody = {
    data: {
      name: payload.formTitle,
      notes: description,
      workspace: config.workspaceGid,
      projects: config.projectGids ?? [],
    },
  }

  const fetchFn = config.fetch ?? fetch
  const response = await fetchFn('https://app.asana.com/api/1.0/tasks', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.asanaToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(requestBody),
  })

  if (!response.ok) {
    throw new Error(
      `Asana API error: ${response.status} ${response.statusText} for POST https://app.asana.com/api/1.0/tasks`
    )
  }

  const result = (await response.json()) as { data: AsanaTaskResponse }
  return {
    taskId: result.data.gid,
    taskName: result.data.name,
    taskNotes: result.data.notes,
  }
}

